// Per-segment defaults baked at `sb pub add` time. Override at
// construction (`ImageRawTopicOverrides`) to vary the wire
// path without regenerating.
inline constexpr std::string_view ImageRaw_DEFAULT_DEVICE    = "dev01";
inline constexpr std::string_view ImageRaw_DEFAULT_WORKSPACE = "demo";
inline constexpr std::string_view ImageRaw_DEFAULT_MODULE    = "pubber";
inline constexpr std::string_view ImageRaw_DEFAULT_TOPIC     = "image_raw";
inline constexpr std::string_view ImageRaw_TRANSPORT_SEGMENT = "iox2";

// Per-segment override of the canonical wire path
// `<device>/<workspace>/<module>/<transport>/<topic>`. Empty string keeps
// the codegen default. Set `.module = "controller-2"` etc. to discriminate
// swarm instances at runtime; set `.full = "..."` to bypass segment
// assembly entirely. `full` and the per-segment fields are all
// `string_view` — the backing string must outlive the constructor.
struct ImageRawTopicOverrides {
  std::string_view device{};
  std::string_view workspace{};
  std::string_view module{};
  std::string_view topic{};
  std::string_view full{};

  std::string service_name() const {
    if (!full.empty()) return std::string(full);
    auto pick = [](std::string_view ov, std::string_view def) {
      return ov.empty() ? def : ov;
    };
    std::string out;
    out.reserve(64);
    out.append(pick(device,    ImageRaw_DEFAULT_DEVICE));
    out.push_back('/');
    out.append(pick(workspace, ImageRaw_DEFAULT_WORKSPACE));
    out.push_back('/');
    out.append(pick(module,    ImageRaw_DEFAULT_MODULE));
    out.push_back('/');
    out.append(ImageRaw_TRANSPORT_SEGMENT);
    out.push_back('/');
    out.append(pick(topic,     ImageRaw_DEFAULT_TOPIC));
    return out;
  }
};

